INSERT INTO project_guides (repository_id, content, confidence, editorial_updated)
     SELECT id, '{"intro":{"zh":"基于 MCP 协议的 ESP32 语音聊天机器人固件：设备端负责唤醒词、录音与播放，服务端处理语音识别与大模型对话。","en":"An MCP-based ESP32 voice chatbot firmware: the device handles wake word, capture and playback while the server does speech recognition and LLM dialogue."},"prerequisites":[{"zh":"会使用 ESP-IDF 编译并烧录工程","en":"Comfortable building and flashing projects with ESP-IDF"},{"zh":"了解 I2S 音频与基础网络请求","en":"Basic knowledge of I2S audio and HTTP/WebSocket networking"}],"hardware":[{"item":{"zh":"ESP32-S3 开发板（建议 8MB Flash + PSRAM）","en":"ESP32-S3 board (8 MB flash + PSRAM recommended)"},"note":{"zh":"官方支持多块现成板卡，也可自行移植","en":"Several off-the-shelf boards are supported upstream"}},{"item":{"zh":"I2S 数字麦克风","en":"I2S digital microphone"}},{"item":{"zh":"I2S 功放 + 扬声器","en":"I2S amplifier + speaker"}},{"item":{"zh":"可选：SPI 显示屏用于表情/状态","en":"Optional: SPI display for expressions and status"}}],"quickStart":[{"step":{"zh":"准备 ESP-IDF 环境","en":"Set up ESP-IDF"},"detail":{"zh":"按官方文档安装 IDF 并确认 idf.py 可用。","en":"Install IDF per the official docs and confirm idf.py works."}},{"step":{"zh":"选择板型并编译","en":"Pick a board and build"},"detail":{"zh":"用仓库提供的板型配置生成工程，执行 idf.py build。","en":"Generate the project from a supported board profile, then idf.py build."}},{"step":{"zh":"烧录并配网","en":"Flash and provision"},"detail":{"zh":"烧录后设备会开启热点，用手机完成 Wi-Fi 与设备绑定。","en":"After flashing, the device opens a hotspot so you can set Wi-Fi and bind it from a phone."}},{"step":{"zh":"验证一轮对话","en":"Verify one dialogue round"},"detail":{"zh":"唤醒后说一句话，确认设备有回复音频。","en":"Wake it, speak once and confirm audio comes back."}}],"docs":[{"label":{"zh":"官方 README（刷机/配网）","en":"Upstream README (flash/provision)"},"url":"https://github.com/78/xiaozhi-esp32/blob/main/README.md","kind":"doc"},{"label":{"zh":"自定义开发板移植","en":"Custom board porting"},"url":"https://github.com/78/xiaozhi-esp32/blob/main/docs/custom-board.md","kind":"doc"},{"label":{"zh":"配套服务端","en":"Companion server"},"url":"https://github.com/xinnan-tech/xiaozhi-esp32-server","kind":"tutorial"},{"label":{"zh":"官方控制台","en":"Official console"},"url":"https://xiaozhi.me/","kind":"demo"}],"faq":[{"q":{"zh":"没有官方开发板能用吗？","en":"Can I use a non-official board?"},"a":{"zh":"可以，但需要按 custom-board 文档写板型配置（引脚、屏幕、音频），难度明显上升。","en":"Yes, but you must write a board profile (pins, display, audio) following the custom-board docs — a clear step up in difficulty."}},{"q":{"zh":"必须自己部署服务端吗？","en":"Do I have to self-host the server?"},"a":{"zh":"不一定：官方提供了在线服务；自建服务端适合需要私有化或定制模型的场景。","en":"No — an official online service exists. Self-hosting makes sense for privacy or custom models."}}],"limitations":[{"zh":"语音链路依赖网络，离线不可用。","en":"The voice pipeline depends on a network connection; it does not work offline."},{"zh":"不同板卡的音频参数差异大，移植时经常需要反复调 I2S 配置。","en":"Audio parameters differ a lot between boards; porting usually needs repeated I2S tuning."}],"maintenance":{"zh":"仓库近期持续提交并有版本发布，Issue 数量较多说明社区活跃但同时需要先搜历史 Issue。","en":"Actively committed with recent releases. The high issue count means a lively community — search existing issues first."},"nextSteps":[{"zh":"把固件移植到自己的 PCB 并整理引脚表。","en":"Port the firmware to your own PCB and document the pin map."},{"zh":"接入自建服务端，替换成自己的模型与音色。","en":"Point it at a self-hosted server with your own model and voice."}]}', 'verified', '2026-10-25T23:16:00.613Z'
     FROM repositories WHERE full_name = '78/xiaozhi-esp32'
     ON CONFLICT(repository_id) DO UPDATE SET content=excluded.content,
       confidence=excluded.confidence, editorial_updated=excluded.editorial_updated;
INSERT INTO project_guides (repository_id, content, confidence, editorial_updated)
     SELECT id, '{"intro":{"zh":"小智硬件的后端：接收设备音频、调用语音识别与大模型、合成语音回传，并提供设备与配置管理。","en":"The backend for XiaoZhi hardware: receives device audio, calls ASR and LLMs, synthesises speech, and manages devices and configuration."},"prerequisites":[{"zh":"熟悉 Docker 与容器编排","en":"Comfortable with Docker"},{"zh":"了解 WebSocket 与流式音频","en":"Understanding of WebSocket and streaming audio"}],"hardware":[{"item":{"zh":"一台可运行容器的主机（本地或云服务器）","en":"A host able to run containers (local or cloud)"}}],"quickStart":[{"step":{"zh":"准备环境","en":"Prepare the host"},"detail":{"zh":"安装 Docker，预留可用端口与存储。","en":"Install Docker and free up ports and disk."}},{"step":{"zh":"启动服务","en":"Start the service"},"detail":{"zh":"按 README 的 compose 配置启动，检查日志无报错。","en":"Start it with the compose config from the README and check the logs."}},{"step":{"zh":"配置模型与音色","en":"Configure models and voices"},"detail":{"zh":"在管理界面填入 ASR/LLM/TTS 的凭据。","en":"Enter ASR/LLM/TTS credentials in the admin UI."}},{"step":{"zh":"设备联调","en":"Connect a device"},"detail":{"zh":"把设备指向你的服务端地址并完成一轮对话。","en":"Point a device at your server and complete one dialogue round."}}],"docs":[{"label":{"zh":"仓库 README","en":"Repo README"},"url":"https://github.com/xinnan-tech/xiaozhi-esp32-server","kind":"doc"},{"label":{"zh":"设备端固件","en":"Device firmware"},"url":"https://github.com/78/xiaozhi-esp32","kind":"tutorial"}],"faq":[{"q":{"zh":"必须用付费模型吗？","en":"Do I need paid models?"},"a":{"zh":"取决于你选的 provider；仓库支持多种可替换的语音与大模型服务，成本由你自己控制。","en":"That depends on the provider you choose; multiple swappable speech and LLM services are supported, so you control cost."}}],"limitations":[{"zh":"自建服务端需要自己承担可用性、密钥管理与费用。","en":"Self-hosting means you own availability, key management and cost."}],"maintenance":{"zh":"活跃开发中，版本迭代较快，部署前请锁定 tag。","en":"Actively developed with fast iteration — pin a tag before deploying."},"nextSteps":[{"zh":"接入自有知识库或私有模型。","en":"Wire in your own knowledge base or private model."}]}', 'verified', '2026-10-25T23:16:00.613Z'
     FROM repositories WHERE full_name = 'xinnan-tech/xiaozhi-esp32-server'
     ON CONFLICT(repository_id) DO UPDATE SET content=excluded.content,
