INSERT INTO project_guides (repository_id, content, confidence, editorial_updated)
     SELECT id, '{"intro":{"zh":"把 ESP8266/ESP32 智能设备变成可本地控制的节点：Web 界面配置、MQTT、Home Assistant 自动发现与 Matter 桥接。","en":"Turns ESP8266/ESP32 smart devices into locally controlled nodes: web configuration, MQTT, Home Assistant discovery and Matter bridging."},"prerequisites":[{"zh":"无需编程基础即可上手","en":"No programming needed to get started"},{"zh":"了解 MQTT 主题与 broker 概念更佳","en":"MQTT topics and brokers help"}],"hardware":[{"item":{"zh":"ESP32 或 ESP8266 设备（插座、继电器、灯具等）","en":"An ESP32/ESP8266 device (plug, relay, light)"}},{"item":{"zh":"USB 转 TTL 烧录器（首次刷机通常需要）","en":"USB-TTL adapter (usually required for the first flash)"}}],"quickStart":[{"step":{"zh":"备份原厂固件","en":"Back up the stock firmware"},"detail":{"zh":"先导出原固件以便回退，再动手刷机。","en":"Dump the original firmware first so you can roll back."}},{"step":{"zh":"网页刷机","en":"Flash from the browser"},"detail":{"zh":"用官方 installer 选择对应模板烧录。","en":"Use the official installer with the matching template."}},{"step":{"zh":"配置 Wi-Fi 与 MQTT","en":"Configure Wi-Fi and MQTT"},"detail":{"zh":"设备起热点，填 Wi-Fi 与 broker 信息。","en":"The device opens a hotspot; enter Wi-Fi and broker details."}},{"step":{"zh":"接入 Home Assistant","en":"Add to Home Assistant"},"detail":{"zh":"开启自动发现，确认实体出现。","en":"Enable discovery and confirm entities appear."}}],"docs":[{"label":{"zh":"官方入门文档","en":"Getting started"},"url":"https://tasmota.github.io/docs/Getting-Started/","kind":"doc"},{"label":{"zh":"网页刷机工具","en":"Web installer"},"url":"https://tasmota.github.io/install/","kind":"demo"}],"faq":[{"q":{"zh":"刷坏了怎么办？","en":"What if I brick it?"},"a":{"zh":"多数设备可通过 TTL 串口重新刷入；务必先备份原固件。","en":"Most devices can be re-flashed over TTL serial — hence the backup step."}}],"limitations":[{"zh":"不同硬件的 GPIO 模板差异大，选错模板可能控制到错误的引脚。","en":"GPIO templates differ per device; picking the wrong one can drive the wrong pin."}],"maintenance":{"zh":"长期稳定维护，版本节奏规律。","en":"Long-term stable maintenance with a regular release cadence."},"nextSteps":[{"zh":"用 Berry 脚本做本地自动化。","en":"Add local a