     SELECT id, '{"intro":{"zh":"离网 LoRa 网格通信固件：无需基站与手机信号，多台设备自动组网互发消息，配合手机 App 使用。","en":"Off-grid LoRa mesh firmware: nodes form a network and exchange messages without towers or cell coverage, driven from a phone app."},"prerequisites":[{"zh":"了解当地无线电法规","en":"Know your local radio regulations"}],"hardware":[{"item":{"zh":"受支持的 ESP32 + LoRa 板卡（如 Heltec、T-Beam 类）","en":"A supported ESP32 + LoRa board"}},{"item":{"zh":"匹配频段的天线（务必接好再上电）","en":"A band-matched antenna (always attach before powering on)"}},{"item":{"zh":"手机（蓝牙配置）","en":"A phone for Bluetooth configuration"}}],"quickStart":[{"step":{"zh":"刷固件","en":"Flash firmware"},"detail":{"zh":"用 flasher.meshtastic.org 选择你的板型。","en":"Pick your board at flasher.meshtastic.org."}},{"step":{"zh":"手机配对","en":"Pair from the phone"},"detail":{"zh":"安装 App 并通过蓝牙连接设备。","en":"Install the app and connect over Bluetooth."}},{"step":{"zh":"设置频道与区域","en":"Set channel and region"},"detail":{"zh":"区域必须与法规一致，否则发射功率与频段非法。","en":"The region must match local law or the band and power are illegal."}},{"step":{"zh":"两台设备互发消息","en":"Message between two nodes"},"detail":{"zh":"确认收件箱收到对方文本。","en":"Confirm the other node''s text arrives."}}],"docs":[{"label":{"zh":"官方入门","en":"Getting started"},"url":"https://meshtastic.org/docs/getting-started/","kind":"doc"},{"label":{"zh":"支持硬件清单","en":"Supported hardware"},"url":"https://meshtastic.org/docs/hardware/devices/","kind":"doc"},{"label":{"zh":"网页刷机","en":"Web flasher"},"url":"https://flasher.meshtastic.org/","kind":"demo"}],"faq":[{"q":{"zh":"为什么实际距离远小于宣传？","en":"Why is real range far below the marketing?"},"a":{"zh":"视距、天线质量、遮挡与发射功率限制共同决定；城市环境通常只有几百米到几公里。","en":"Line of sight, antenna quality, obstruction and legal power limits all matter — urban links are typically hundreds of metres to a few km."}}],"limitations":[{"zh":"ESP32 版本功耗高于 nRF52 版本，长期电池供电不占优势。","en":"ESP32 builds draw more power than nRF52 builds, so they are weaker for long battery life."}],"maintenance":{"zh":"活跃维护，固件与 App 同步