     SELECT id, '{"intro":{"zh":"Wi-Fi/蓝牙扫描与测试工具套件，用于评估自有网络与设备的安全状况。请只在获得授权的环境中使用。","en":"A Wi-Fi/Bluetooth scanning and testing suite for auditing networks and devices you own. Use it only where you are authorised."},"prerequisites":[{"zh":"了解 Wi-Fi/BLE 基础概念","en":"Basic Wi-Fi and BLE concepts"},{"zh":"明确的法律与授权边界","en":"A clear legal and authorisation boundary"}],"hardware":[{"item":{"zh":"ESP32 或 ESP32-S3 开发板","en":"An ESP32 or ESP32-S3 board"}},{"item":{"zh":"可选：触摸屏与 GPS 模块","en":"Optional: touchscreen and GPS module"}}],"quickStart":[{"step":{"zh":"编译并烧录","en":"Build and flash"},"detail":{"zh":"按 README 用 PlatformIO/Arduino 构建。","en":"Build with PlatformIO/Arduino per the README."}},{"step":{"zh":"从串口菜单操作","en":"Use the serial menu"},"detail":{"zh":"通过串口或屏幕菜单选择扫描与测试功能。","en":"Pick scanning and test features from the serial or on-screen menu."}},{"step":{"zh":"只在自有网络测试","en":"Test only on your own networks"},"detail":{"zh":"先确认授权范围，再执行任何主动测试。","en":"Confirm your authorisation before any active test."}}],"docs":[{"label":{"zh":"仓库 Wiki","en":"Repo wiki"},"url":"https://github.com/justcallmekoko/ESP32Marauder/wiki","kind":"doc"}],"faq":[{"q":{"zh":"可以用来测试公共 Wi-Fi 吗？","en":"Can I test public Wi-Fi?"},"a":{"zh":"不建议也不合法。未经授权对他人网络做主动测试在多数司法辖区违法。","en":"No. Active testing of networks you do not own is illegal in most jurisdictions."}}],"limitations":[{"zh":"部分功能依赖特定硬件（屏幕、GPS、SD 卡）。","en":"Some features depend on extra hardware such as a display, GPS or SD card."}],"maintenance":{"zh":"活跃维护。","en":"Actively maintained."},"nextSteps":[{"zh":"用扫描结果加固自己的 AP 配置。","en":"Use scan results to harden your own access points."}]}', 'verified', '2026-10-25T23:16:00.613Z'
