     SELECT id, '{"intro":{"zh":"乐鑫官方开发框架（C/C++ + FreeRTOS），提供完整驱动、组件管理、构建系统与安全能力，是量产项目的基准。","en":"Espressif''s official framework (C/C++ + FreeRTOS) with complete drivers, component management, build system and security features — the baseline for production."},"prerequisites":[{"zh":"C 语言与命令行基础","en":"C and command-line basics"},{"zh":"理解任务/队列等多任务概念更佳","en":"Task/queue concepts help"}],"hardware":[{"item":{"zh":"任意受支持的 ESP32 系列开发板","en":"Any supported ESP32-series board"}}],"quickStart":[{"step":{"zh":"安装工具链","en":"Install the toolchain"},"detail":{"zh":"按官方 get-started 安装，或使用 VS Code 扩展。","en":"Follow the official get-started guide or use the VS Code extension."}},{"step":{"zh":"编译 hello_world","en":"Build hello_world"},"detail":{"zh":"idf.py set-target / build / flash / monitor。","en":"idf.py set-target / build / flash / monitor."}},{"step":{"zh":"切换到自己的工程","en":"Move to your project"},"detail":{"zh":"用 idf.py create-project 建立组件化工程。","en":"Create a componentised project with idf.py create-project."}}],"docs":[{"label":{"zh":"Get Started","en":"Get Started"},"url":"https://docs.espressif.com/projects/esp-idf/en/stable/esp32/get-started/index.html","kind":"doc"},{"label":{"zh":"官方示例","en":"Official examples"},"url":"https://github.com/espressif/esp-idf/tree/master/examples","kind":"tutorial"},{"label":{"zh":"组件管理器","en":"Component registry"},"url":"https://components.espressif.com/","kind":"tool"}],"faq":[{"q":{"zh":"和 Arduino 怎么选？","en":"IDF or Arduino?"},"a":{"zh":"原型与教学用 Arduino 更快；需要精细控制、低功耗与安全特性时选 IDF。","en":"Arduino is faster for prototypes and teaching; choose IDF when you need fine control, low power and security features."}}],"limitations":[{"zh":"学习曲线陡峭，构建与配置概念较多。","en":"Steep learning curve with many build and configuration concepts."}],"maintenance":{"zh":"官方长期维护，多分支发布。","en":"Officially maintained with multiple release branches."},"nextSteps":[{"zh":"阅读官方 security 指南，规划量产烧录。","en":"Read the security guides and plan manufacturing flashing."}]}', 'veri