     SELECT id, '{"intro":{"zh":"乐鑫官方 Arduino 核心：让 ESP32 全系列能在 Arduino IDE / PlatformIO 中开发，是新手最快的上手路径。","en":"Espressif''s official Arduino core, letting the whole ESP32 family build in Arduino IDE or PlatformIO — the fastest on-ramp for beginners."},"prerequisites":[{"zh":"无（懂一点 C 更顺）","en":"None (a little C helps)"}],"hardware":[{"item":{"zh":"ESP32 开发板 + USB 线","en":"An ESP32 board and a USB cable"}}],"quickStart":[{"step":{"zh":"添加板管理器地址","en":"Add the boards URL"},"detail":{"zh":"在首选项里填入官方 JSON 地址。","en":"Paste the official JSON URL in preferences."}},{"step":{"zh":"安装 esp32 核心","en":"Install the esp32 core"},"detail":{"zh":"在板管理器里安装最新稳定版。","en":"Install the latest stable core."}},{"step":{"zh":"上传 Blink","en":"Upload Blink"},"detail":{"zh":"选对板型与串口，编译上传。","en":"Select the right board and port, then upload."}}],"docs":[{"label":{"zh":"安装指南","en":"Install guide"},"url":"https://docs.espressif.com/projects/arduino-esp32/en/latest/installing.html","kind":"doc"},{"label":{"zh":"Wi-Fi API","en":"Wi-Fi API"},"url":"https://docs.espressif.com/projects/arduino-esp32/en/latest/api/wifi.html","kind":"doc"},{"label":{"zh":"内置库目录","en":"Bundled libraries"},"url":"https://github.com/espressif/arduino-esp32/tree/master/libraries","kind":"tutorial"}],"faq":[{"q":{"zh":"上传一直失败？","en":"Uploads keep failing?"},"a":{"zh":"检查板型、串口驱动与 BOOT 按键；部分板子需要手动进入下载模式。","en":"Check board selection, the USB driver and the BOOT button — some boards need manual download mode."}}],"limitations":[{"zh":"抽象较高，做低功耗与实时性调优会比 IDF 麻烦。","en":"Higher abstraction makes low-power and real-time tuning harder than IDF."}],"maintenance":{"zh":"官方维护，版本随 IDF 更新。","en":"Officially maintained, tracking IDF releases."},"nextSteps":[{"zh":"熟悉后迁移到 PlatformIO 或 IDF。","en":"Move to PlatformIO or IDF once comfortable."}]}', 'verified', '2026-10-25T23:16:00.613Z'
