     SELECT id, '{"intro":{"zh":"经典的多传感器 + MQTT 教学项目（温湿度/气压/光照），代码简洁易读，适合学习数据上报结构。","en":"A classic multi-sensor + MQTT teaching project (temp/humidity/pressure/light) with small, readable code for learning telemetry structure."},"prerequisites":[{"zh":"Arduino 基础","en":"Arduino basics"},{"zh":"有 MQTT broker","en":"An MQTT broker"}],"hardware":[{"item":{"zh":"ESP8266 或 ESP32 开发板","en":"ESP8266 or ESP32 board"},"note":{"zh":"原始项目面向 ESP8266","en":"The original targets ESP8266"}},{"item":{"zh":"DHT22、BMP180、光敏电阻","en":"DHT22, BMP180 and a photoresistor"}}],"quickStart":[{"step":{"zh":"读懂代码结构","en":"Read the code"},"detail":{"zh":"先看 MQTT 主题与 JSON 组装方式。","en":"Start with the MQTT topics and JSON assembly."}},{"step":{"zh":"按当前版本改依赖","en":"Update dependencies"},"detail":{"zh":"老库版本可能已不兼容，需换成当前维护的库。","en":"Old library versions may not compile — swap in maintained ones."}},{"step":{"zh":"验证上报","en":"Verify publishing"},"detail":{"zh":"用 MQTT 客户端订阅并检查 JSON 字段。","en":"Subscribe with an MQTT client and inspect the JSON fields."}}],"docs":[{"label":{"zh":"仓库 README","en":"Repo README"},"url":"https://github.com/bruhautomation/ESP-MQTT-JSON-Multisensor","kind":"doc"}],"faq":[{"q":{"zh":"为什么编译不过？","en":"Why does it not compile?"},"a":{"zh":"项目已多年未更新，依赖与 API 变化会导致编译失败，属正常现象。","en":"The repo has not been updated for years, so dependency and API drift will break the build — expected."}}],"limitations":[{"zh":"已停止维护，硬件清单与库版本需要按现状调整。","en":"Unmaintained: adapt the parts list and library versions yourself."}],"maintenance":{"zh":"已长期无更新，仅作学习参考。","en":"Dormant for years — reference only."},"nextSteps":[{"zh":"用 ESPHome 重写同样功能，维护成本更低。","en":"Reimplement the same features in ESPHome for far lower maintenance cost."}]}', 'unverified', '2026-10-25T23:16:00.613Z'
