     VALUES ('zero-to-esp32', '{"zh":"零基础 ESP32","en":"ESP32 from zero"}', '{"zh":"从没碰过单片机开始：认识开发板、装好工具链、点亮第一个 LED，再到能联网上报数据。","en":"Never touched a microcontroller: meet the board, install the toolchain, blink an LED, then report data over the network."}', 'beginner', '10–16 h',
       '["esp32","esp32-c3"]', '["arduino"]', 'cpu', 0)
     ON CONFLICT(slug) DO UPDATE SET title_i18n=excluded.title_i18n,
       summary_i18n=excluded.summary_i18n, level=excluded.level, hours=excluded.hours,
       chips=excluded.chips, frameworks=excluded.frameworks, icon=excluded.icon,
       sort_order=excluded.sort_order;
INSERT INTO learning_path_steps (path_id, step_no, title_i18n, goal_i18n, prereq_i18n,
         resources, projects, estimate, done_when_i18n)
       SELECT id, 1, '{"zh":"认识硬件与安全","en":"Meet the hardware"}', '{"zh":"分清芯片型号、开发板与模块，知道 USB 供电与 3.3V 逻辑的基本约束。","en":"Tell chips, boards and modules apart and know the 3.3V / USB power constraints."}', 'null',
         '[{"label":{"zh":"ESP32 芯片选型指南","en":"ESP32 chip guide"},"url":"https://randomnerdtutorials.com/esp32-chip-guide/","kind":"tutorial"},{"label":{"zh":"引脚参考（启动引脚）","en":"Pinout reference"},"url":"https://randomnerdtutorials.com/esp32-pinout-reference-gpios/","kind":"tutorial"}]', '[]', '1–2 h', '{"zh":"能在自己的板子上指出 BOOT、EN、3V3、GND 与至少两个可用 GPIO。","en":"You can point at BOOT, EN, 3V3, GND and two usable GPIOs on your own board."}'
       FROM learning_paths WHERE slug = 'zero-to-esp32'
       ON CONFLICT(path_id, step_no) DO UPDATE SET title_i18n=excluded.title_i18n,
         goal_i18n=excluded.goal_i18n, prereq_i18n=excluded.prereq_i18n,
         resources=excluded.resources, projects=excluded.projects,
         estimate=excluded.estimate, done_when_i18n=excluded.done_when_i18n;
INSERT INTO learning_path_steps (path_id, step_no, title_i18n, goal_i18n, prereq_i18n,
         resources, projects, estimate, done_when_i18n)
       SELECT id, 2, '{"zh":"装好开发环境","en":"Install the toolchain"}', '{"zh":"在 Arduino IDE 中安装 ESP32 核心，并能成功编译上传一个空白程序。","en":"Install the ESP32 core in Arduino IDE and upload an empty sketch successfully."}', 'null',
         '[{"label":{"zh":"Arduino-ESP32 安装指南","en":"Arduino-ESP32 install"},"url":"https://docs.espressif.com/projects/arduino-esp32/en/latest/installing.html","kind":"doc"},{"label":{"zh":"Arduino IDE 文档","en":"Arduino IDE docs"},"url":"https://docs.arduino.cc/software/ide/","kind":"doc"}]', '["espressif/arduino-esp32"]', '1–3 h', '{"zh":"串口监视器能打印出你写的文字，且没有上传报错。","en":"The serial monitor prints your text and the upload completes without errors."}'
       FROM learning_paths WHERE slug = 'zero-to-esp32'
       ON CONFLICT(path_id, step_no) DO UPDATE SET title_i18n=excluded.title_i18n,
         goal_i18n=excluded.goal_i18n, prereq_i18n=excluded.prereq_i18n,
         resources=excluded.resources, projects=excluded.projects,
         estimate=excluded.estimate, done_when_i18n=excluded.done_when_i18n;
INSERT INTO learning_path_steps (path_id, step_no, title_i18n, goal_i18n, prereq_i18n,
         resources, projects, estimate, done_when_i18n)
       SELECT id, 3, '{"zh":"GPIO 与 PWM 输出","en":"GPIO and PWM output"}', '{"zh":"用数字输出点灯、用 LEDC 做呼吸灯，理解占空比。","en":"Blink with digital output, then build a breathing LED with LEDC and understand duty cycle."}', 'null',
         '[{"label":{"zh":"ESP32 PWM 教程","en":"ESP32 PWM tutorial"},"url":"https://randomnerdtutorials.com/esp32-pwm-arduino-ide/","kind":"tutorial"},{"label":{"zh":"ESP-IDF GPIO 文档","en":"ESP-IDF GPIO docs"},"url":"https://docs.espressif.com/projects/esp-idf/en/stable/esp32/api-reference/peripherals/gpio.html","kind":"doc"}]', '["FastLED/FastLED"]', '2–3 h', '{"zh":"你能不看教程写出一个渐变呼吸灯，并解释为什么亮度不是线性的。","en":"You can write a fading LED without the tutorial and explain why brightness is not linear."}'
       FROM learning_paths WHERE slug = 'zero-to-esp32'
       ON CONFLICT(path_id, step_no) DO UPDATE SET title_i18n=excluded.title_i18n,
         goal_i18n=excluded.goal_i18n, prereq_i18n=excluded.prereq_i18n,
         resources=excluded.resources, projects=excluded.projects,
         estimate=excluded.estimate, done_when_i18n=excluded.done_when_i18n;
INSERT INTO learning_path_steps (path_id, step_no, title_i18n, goal_i18n, prereq_i18n,
         resources, projects, estimate, done_when_i18n)
       SELECT id, 4, '{"zh":"模拟输入与传感器","en":"Analog input and sensors"}', '{"zh":"读 ADC 与 I2C 传感器数据，并在串口里观察噪声与漂移。","en":"Read ADC and an I2C sensor, watching noise and drift on the serial monitor."}', 'null',
         '[{"label":{"zh":"ADC 读取教程","en":"ADC reading tutorial"},"url":"https://randomnerdtutorials.com/esp32-adc-analog-read-arduino-ide/","kind":"tutorial"},{"label":{"zh":"I2C 通信与地址扫描","en":"I2C and address scanning"},"url":"https://randomnerdtutorials.com/esp32-i2c-communication-arduino-ide/","kind":"tutorial"},{"label":{"zh":"DHT11/DHT22 温湿度","en":"DHT11/DHT22 sensor"},"url":"https://randomnerdtutorials.com/esp32-dht11-dht22-temperature-humidity-sensor-arduino-ide/","kind":"tutorial"}]', '["bruhautomation/ESP-MQTT-JSON-Multisensor"]', '2–4 h', '{"zh":"你能自己排查「读不到设备」：先扫 I2C 地址，再查供电与上拉。","en":"You can debug “no device found” yourself: scan I2C addresses first, then check power and pull-ups."}'
       FROM learning_paths WHERE slug = 'zero-to-esp32'
       ON CONFLICT(path_id, step_no) DO UPDATE SET title_i18n=excluded.title_i18n,
         goal_i18n=excluded.goal_i18n, prereq_i18n=excluded.prereq_i18n,
