INSERT INTO learning_path_steps (path_id, step_no, title_i18n, goal_i18n, prereq_i18n,
         resources, projects, estimate, done_when_i18n)
       SELECT id, 5, '{"zh":"联网与第一个 Web 界面","en":"Networking and a first web UI"}', '{"zh":"连上 Wi-Fi，起一个 HTTP 服务，把传感器数据显示在网页上。","en":"Join Wi-Fi, serve HTTP, and show sensor readings in a web page."}', 'null',
         '[{"label":{"zh":"ESP32 Web Server 教程","en":"ESP32 web server"},"url":"https://randomnerdtutorials.com/esp32-web-server-arduino-ide/","kind":"tutorial"},{"label":{"zh":"Arduino Wi-Fi API","en":"Arduino Wi-Fi API"},"url":"https://docs.espressif.com/projects/arduino-esp32/en/latest/api/wifi.html","kind":"doc"},{"label":{"zh":"WiFiManager 配网库","en":"WiFiManager"},"url":"https://github.com/tzapu/WiFiManager","kind":"project"}]', '["tzapu/WiFiManager"]', '3–5 h', '{"zh":"手机在同一 Wi-Fi 下能打开板子的网页，并看到实时数值。","en":"A phone on the same network opens the board''s page and sees live values."}'
       FROM learning_paths WHERE slug = 'zero-to-esp32'
       ON CONFLICT(path_id, step_no) DO UPDATE SET title_i18n=excluded.title_i18n,
