         estimate=excluded.estimate, done_when_i18n=excluded.done_when_i18n;
INSERT INTO learning_paths (slug, title_i18n, summary_i18n, level, hours, chips, frameworks,
       icon, sort_order)
     VALUES ('arduino-esp32', '{"zh":"Arduino-ESP32 进阶","en":"Arduino-ESP32 in depth"}', '{"zh":"已经把灯点亮了？这一条路线把 Arduino 核心的能力用满：任务调度、中断、文件系统、WebSocket 与 OTA。","en":"Already blinking? This path uses the Arduino core properly: task scheduling, interrupts, filesystem, WebSockets and OTA."}', 'intermediate', '20–30 h',
       '["esp32","esp32-s3","esp32-c3"]', '["arduino"]', 'code', 1)
     ON CONFLICT(slug) DO UPDATE SET title_i18n=excluded.title_i18n,
