         '[{"label":{"zh":"Arduino-ESP32 库目录","en":"Bundled libraries"},"url":"https://github.com/espressif/arduino-esp32/tree/master/libraries","kind":"project"}]', '["espressif/arduino-esp32"]', '2 h', '{"zh":"能说出三个场景各该用哪个官方库，并找到对应示例。","en":"For three scenarios you can name the right official library and its example."}'
       FROM learning_paths WHERE slug = 'arduino-esp32'
