INSERT INTO learning_path_steps (path_id, step_no, title_i18n, goal_i18n, prereq_i18n,
         resources, projects, estimate, done_when_i18n)
       SELECT id, 2, '{"zh":"并发与中断","en":"Concurrency and interrupts"}', '{"zh":"区分 loop 阻塞、FreeRTOS 任务与 ISR，写出不卡住 Wi-Fi 的代码。","en":"Separate blocking loop code, FreeRTOS tasks and ISRs so Wi-Fi never stalls."}', 'null',
         '[{"label":{"zh":"Arduino-ESP32 中的 FreeRTOS（示例）","en":"FreeRTOS in Arduino-ESP32"},"url":"https://github.com/espressif/arduino-esp32/tree/master/libraries/ESP32/examples","kind":"project"},{"label":{"zh":"GPIO 中断文档","en":"GPIO interrupt docs"},"url":"https://docs.espressif.com/projects/esp-idf/en/stable/esp32/api-reference/peripherals/gpio.html","kind":"doc"}]', '["espressif/arduino-esp32"]', '4–6 h', '{"zh":"你能写一个按钮中断 + 后台定时上报的组合，且不会丢事件。","en":"You can combine a button ISR with periodic reporting without dropping events."}'
       FROM learning_paths WHERE slug = 'arduino-esp32'
