         '[{"label":{"zh":"ESP32 WebSocket 教程","en":"ESP32 WebSocket"},"url":"https://randomnerdtutorials.com/esp32-web-server-websocket/","kind":"tutorial"}]', '["espressif/arduino-esp32"]', '4–6 h', '{"zh":"断开 Wi-Fi 后客户端能自动恢复，且板子不重启。","en":"Clients recover automatically after Wi-Fi drops, and the board does not reboot."}'
